"""PL-01 step 3: put every ticker on one calendar."""

from __future__ import annotations

from collections.abc import Sequence

from mdata.types import GapError, Prices, RawRow


def align_calendar(rows: Sequence[RawRow], *, max_gap: int = 5) -> Prices:
    """Prices from the first date every ticker has a close; GapError past `max_gap` missing dates.

    The calendar is every date any ticker has a close on, starting from the first date on which
    every ticker has one. A ticker missing a date takes its previous close.
    """
    closes_by_ticker: dict[str, dict[str, float]] = {}
    for row in rows:
        by_date = closes_by_ticker.setdefault(row.ticker, {})
        if row.close is not None:
            by_date[row.date] = row.close
    tickers = tuple(sorted(closes_by_ticker))
    dates = _calendar([closes_by_ticker[ticker] for ticker in tickers])
    closes = {
        ticker: _forward_fill(ticker, closes_by_ticker[ticker], dates, max_gap)
        for ticker in tickers
    }
    return Prices(dates=dates, tickers=tickers, closes=closes)


def _calendar(closes: list[dict[str, float]]) -> tuple[str, ...]:
    """Every date any ticker has a close on, from the first date on which every ticker has one."""
    if not closes or not all(closes):
        return ()
    start = max(min(by_date) for by_date in closes)
    return tuple(sorted({date for by_date in closes for date in by_date if date >= start}))


def _forward_fill(
    ticker: str, by_date: dict[str, float], dates: tuple[str, ...], max_gap: int
) -> tuple[float, ...]:
    """`ticker`'s close on each date, a missing date taking the previous close."""
    filled: list[float] = []
    missing = 0
    for date in dates:
        if date in by_date:
            filled.append(by_date[date])
            missing = 0
            continue
        missing += 1
        if missing > max_gap:
            msg = f"{ticker} misses more than {max_gap} dates in a row, through {date}"
            raise GapError(msg)
        filled.append(filled[-1])
    return tuple(filled)

